-- +goose Up
-- The content review of 2026-10-27 (client): terms gain renewal and refund rules and lose the marketplace
-- leftovers; privacy covers the sign-up form, the password login and the visitor count; about and the FAQ follow
-- the plan table and the metal auctions; the brand is «الان‌فلز». Pages keep the previous text as a revision, and
-- every change applies only where the seed text is still there (edits made in the admin are left alone).

-- +goose StatementBegin
WITH n AS (SELECT p.slug, p.title_fa AS title, replace(replace(p.body_fa, '<li>اطلاعات حراج‌ها و عرضه‌های روزانه</li>', '<li>اطلاعات مزایده‌های فلزات: شمش و محصولات میانی، ضایعات و مواد اولیه</li>'), '<li><strong>ل — لحظه‌ای بودن اطلاعات:</strong> قیمت فلزات هر لحظه تغییر می‌کند؛ اطلاعات ما هم همان لحظه به‌روز می‌شود.</li>', '<li><strong>ل — لحظه به لحظه همراه بازار:</strong> قیمت‌ها به‌طور پیوسته به‌روز می‌شوند و زمان آخرین به‌روزرسانی کنار هر قیمت نمایش داده می‌شود.</li>') AS body FROM app.pages p WHERE p.slug = 'about'),
r AS (
  INSERT INTO app.page_revisions (slug, version, title_fa, title_en, body_fa, body_en)
  SELECT p.slug, p.version, p.title_fa, p.title_en, p.body_fa, p.body_en FROM app.pages p JOIN n ON n.slug = p.slug
  WHERE p.body_fa <> n.body OR p.title_fa <> n.title
  ON CONFLICT (slug, version) DO NOTHING
)
UPDATE app.pages p SET title_fa = n.title, body_fa = n.body, version = p.version + 1, updated_at = now()
FROM n WHERE p.slug = n.slug AND (p.body_fa <> n.body OR p.title_fa <> n.title);
-- +goose StatementEnd

-- +goose StatementBegin
WITH n AS (SELECT p.slug, replace(p.title_fa, 'الان فلز', 'الان‌فلز') AS title, replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(p.body_fa, '<p>الان فلز یک پلتفرم تخصصی در حوزه اطلاعات، قیمت‌ها، داده‌ها و ارتباطات تجاری بازار فلزات است.</p>', '<p>الان‌فلز یک پلتفرم تخصصی در حوزه اطلاعات، قیمت‌ها و داده‌های بازار فلزات است.</p>'), '<li>ارائه اطلاعات بازار داخلی و بین‌المللی</li>', '<li>ارائه اطلاعات بازار داخلی و بین‌المللی</li>
<li>انتشار اطلاعات مزایده‌های فلزات</li>'), '<p>الان فلز در مواردی که صرفاً نقش ارائه‌دهنده اطلاعات یا بستر ارتباطی دارد، فروشنده، خریدار، مالک، تولیدکننده، نماینده یا واسطه قانونی کالاهای معرفی‌شده توسط کاربران محسوب نمی‌شود؛ مگر اینکه صراحتاً خلاف آن اعلام شده باشد.</p>', '<p>الان‌فلز فروشنده، خریدار، مالک، تولیدکننده، نماینده یا واسطه‌ی قانونی کالاها نیست و برگزارکننده‌ی مزایده‌هایی که اطلاعات آن‌ها در سایت منتشر می‌شود نیز نیست. شرایط، مهلت، برگزاری و نتیجه‌ی هر مزایده بر عهده‌ی برگزارکننده‌ی آن است و کاربر باید آن‌ها را در آگهی رسمی برگزارکننده بررسی کند.</p>'), '<p>کاربر متعهد است هنگام ثبت آگهی یا استفاده از خدمات سایت، اطلاعات صحیح و قابل استناد ارائه کند.</p>', '<p>کاربر متعهد است هنگام ثبت‌نام، ارسال پیام یا تیکت و استفاده از خدمات سایت، اطلاعات صحیح و قابل استناد ارائه کند.</p>'), '<li>حذف یا ویرایش آگهی</li>', '<li>حذف یا ویرایش اطلاعات یا پیام</li>'), '<p>این موضوع به معنی تأیید صحت سایر آگهی‌ها یا محتوای باقی‌مانده در سایت نیست.</p>', '<p>این موضوع به معنی تأیید صحت سایر محتوای باقی‌مانده در سایت نیست.</p>'), '<li>عدم انجام معامله توسط طرف مقابل</li>
<li>اختلاف میان خریدار و فروشنده</li>
<li>اطلاعات نادرست ارائه‌شده توسط کاربر دیگر</li>', '<li>شرایط، تغییر، توقف یا لغو مزایده‌ها از سوی برگزارکننده‌ی آن‌ها</li>'), 'تحقق پیش‌بینی‌ها یا انجام معامله میان کاربران ارائه نمی‌کند', 'تحقق پیش‌بینی‌ها یا برگزاری و نتیجه‌ی مزایده‌ها ارائه نمی‌کند'), '<h2>۱۳. پرداخت‌ها</h2>', '<h3>مدت، تمدید و ارتقای اشتراک</h3>
<ul>
<li>اشتراک ماهانه ۳۰ روز، سه‌ماهه ۹۰ روز و سالانه ۳۶۵ روز اعتبار دارد و بلافاصله پس از تأیید پرداخت فعال می‌شود.</li>
<li>اشتراک به‌صورت خودکار تمدید نمی‌شود و هیچ مبلغی بدون پرداخت مستقیم کاربر کسر نمی‌شود. پیش از پایان اشتراک، یادآوری از طریق پیامک ارسال می‌شود.</li>
<li>اگر همان اشتراک پیش از پایان آن دوباره خریداری شود، دوره‌ی جدید از پایان دوره‌ی فعلی شروع می‌شود.</li>
<li>ارتقا از نقره‌ای به طلایی در هر زمان ممکن است و بلافاصله فعال می‌شود؛ مبلغ روزهای باقی‌مانده‌ی اشتراک قبلی به‌تناسب از هزینه‌ی ارتقا کسر می‌شود. تغییر به اشتراک پایین‌تر از پایان دوره‌ی فعلی اعمال می‌شود.</li>
</ul>
<h3>بازگشت وجه</h3>
<ul>
<li>تا ۷ روز پس از پرداخت، اگر از هیچ‌یک از امکانات پولی همان اشتراک استفاده نشده باشد، کاربر می‌تواند از بخش حساب کاربری درخواست بازگشت وجه ثبت کند و کل مبلغ پرداختی بازگردانده می‌شود.</li>
<li>منظور از «استفاده»، مشاهده‌ی اطلاعات یا به‌کار بردن ابزارهایی است که فقط با اشتراک نقره‌ای یا طلایی در دسترس است؛ مانند قیمت روز کالا، تاریخچه‌ی کامل نمودار، تحلیل‌ها و پیش‌بینی‌ها، جزئیات مزایدات و ماشین حساب. استفاده از امکانات رایگان، استفاده محسوب نمی‌شود. استفاده از امکانات پولی در سامانه ثبت می‌شود.</li>
<li>پس از استفاده از امکانات پولی یا پس از گذشت ۷ روز، بازگشت وجه ممکن نیست و اشتراک تا پایان دوره‌ی خود فعال می‌ماند.</li>
<li>اشتراکی که پس از اشتراک فعلی خریداری شده و هنوز شروع نشده است، تا پیش از شروع، همواره قابل بازگشت وجه است.</li>
<li>پس از تأیید درخواست، اشتراک مربوط لغو می‌شود و مبلغ ظرف ۷ روز کاری به حساب یا کارتی که کاربر اعلام می‌کند واریز می‌شود.</li>
<li>اگر مبلغی از حساب کسر شود ولی پرداخت تأیید و اشتراک فعال نشود، مبلغ طبق مقررات شبکه‌ی بانکی و درگاه پرداخت، معمولاً ظرف ۷۲ ساعت، به‌طور خودکار به حساب پرداخت‌کننده بازمی‌گردد.</li>
</ul>
<h2>۱۳. پرداخت‌ها</h2>'), 'الان فلز', 'الان‌فلز') AS body FROM app.pages p WHERE p.slug = 'terms'),
r AS (
  INSERT INTO app.page_revisions (slug, version, title_fa, title_en, body_fa, body_en)
  SELECT p.slug, p.version, p.title_fa, p.title_en, p.body_fa, p.body_en FROM app.pages p JOIN n ON n.slug = p.slug
  WHERE p.body_fa <> n.body OR p.title_fa <> n.title
  ON CONFLICT (slug, version) DO NOTHING
)
UPDATE app.pages p SET title_fa = n.title, body_fa = n.body, version = p.version + 1, updated_at = now()
FROM n WHERE p.slug = n.slug AND (p.body_fa <> n.body OR p.title_fa <> n.title);
