WITH n AS (SELECT p.slug, p.title_fa AS title, replace(replace(replace(replace(p.body_fa, '<li><strong>اطلاعات حساب کاربری:</strong> شماره موبایل (برای ثبت‌نام و ورود با کد یک‌بار مصرف)، نام و نام خانوادگی و در صورت تمایل، ایمیل.</li>', '<li><strong>اطلاعات حساب کاربری:</strong> شماره موبایل (که نام کاربری شما هم هست و برای ورود با کد یک‌بار مصرف به کار می‌رود)، رمز عبور (به‌صورت رمزنگاری‌شده و غیرقابل بازیابی؛ حتی کارکنان الان‌فلز آن را نمی‌بینند)، نام و نام خانوادگی یا نام شرکت، زمینه‌ی فعالیت و زمان پذیرش قوانین؛ و در صورت تمایل، فلزات تخصصی، استان، شهر، آدرس و ایمیل.</li>'), '<li>ایجاد و مدیریت حساب کاربری و ورود امن به آن</li>', '<li>ایجاد و مدیریت حساب کاربری و ورود امن به آن</li>
<li>متناسب کردن خدمات و اطلاع‌رسانی‌ها با زمینه‌ی فعالیت و فلزات تخصصی شما</li>'), '<p>سایت فقط از کوکی‌های ضروری برای ورود و حفظ نشست کاربری استفاده می‌کند. آمار بازدید با ابزاری جمع‌آوری می‌شود که روی سرورهای خود الان‌فلز اجرا می‌شود، کوکی ردیابی ندارد و افراد را شناسایی نمی‌کند.</p>', '<p>سایت فقط از کوکی‌های ضروری برای ورود و حفظ نشست کاربری استفاده می‌کند و کوکی ردیابی یا تبلیغاتی ندارد.</p>
<p>برای شمارش تعداد بازدیدکنندگان روزانه، نشانی IP و نوع مرورگر شما با کلیدی که هر روز عوض می‌شود به یک شناسه‌ی یک‌طرفه تبدیل می‌شود؛ خود IP ذخیره نمی‌شود و از این شناسه نمی‌توان شما را شناسایی کرد یا بازدیدهای روزهای مختلف را به هم ربط داد. این آمار فقط به‌صورت تجمیعی (مثلاً تعداد بازدیدکنندگان امروز) نگهداری می‌شود و روی سرورهای خود الان‌فلز در داخل ایران است.</p>'), '<li>گزارش‌های فنی سامانه: تا ۳۰ روز.</li>', '<li>گزارش‌های فنی سامانه: تا ۳۰ روز.</li>
<li>شناسه‌های یک‌طرفه‌ی آمار بازدید: تا ۹۰ روز.</li>') AS body FROM app.pages p WHERE p.slug = 'privacy'),
r AS (
  INSERT INTO app.page_revisions (slug, version, title_fa, title_en, body_fa, body_en)
  SELECT p.slug, p.version, p.title_fa, p.title_en, p.body_fa, p.body_en FROM app.pages p JOIN n ON n.slug = p.slug
  WHERE p.body_fa <> n.body OR p.title_fa <> n.title
  ON CONFLICT (slug, version) DO NOTHING
)
UPDATE app.pages p SET title_fa = n.title, body_fa = n.body, version = p.version + 1, updated_at = now()
FROM n WHERE p.slug = n.slug AND (p.body_fa <> n.body OR p.title_fa <> n.title);
-- +goose StatementEnd

UPDATE app.faq_items SET answer_fa = '<p>خیر. الان‌فلز یک پلتفرم اطلاعات بازار فلزات است؛ کالایی نمی‌فروشد یا نمی‌خرد و برگزارکننده‌ی مزایده‌هایی که اطلاعات آن‌ها در سایت منتشر می‌شود نیز نیست.</p>', answer_en = '<p>No. Alan Felez is a metals market-information platform: it doesn''t sell or buy goods, and it doesn''t run the auctions whose details it publishes.</p>', updated_at = now() WHERE slug = 'does-alanfelez-sell-metals' AND answer_fa = '<p>الان‌فلز در درجه اول یک پلتفرم اطلاعات بازار و ارتباط تجاری است و خود را به‌عنوان فروشنده تمامی محصولات معرفی نمی‌کند.</p>' AND answer_en = '<p>Alan Felez is first and foremost a market-information and business-connection platform, and does not present itself as the seller of all products.</p>';
UPDATE app.faq_items SET answer_fa = '<p>سرعت به‌روزرسانی قیمت‌ها به منبع اطلاعات و نوع بازار بستگی دارد. برخی قیمت‌ها چند بار در روز و برخی روزانه یا در بازه‌های مشخص به‌روزرسانی می‌شوند. زمان آخرین به‌روزرسانی کنار هر قیمت نمایش داده می‌شود.</p>', answer_en = '<p>How often prices update depends on the source and the market: some several times a day, others daily or at set intervals. The last-updated time is shown next to each price.</p>', updated_at = now() WHERE slug = 'are-prices-live' AND answer_fa = '<p>سرعت به‌روزرسانی قیمت‌ها به منبع اطلاعات و نوع بازار بستگی دارد. برخی قیمت‌ها به‌صورت لحظه‌ای یا نزدیک به لحظه و برخی دیگر به‌صورت روزانه یا در بازه‌های مشخص به‌روزرسانی می‌شوند. زمان آخرین به‌روزرسانی در بخش مربوط به قیمت نمایش داده شود.</p>' AND answer_en = '<p>How often prices update depends on the data source and the market. Some prices update live or near-live, others daily or at set intervals. The last-updated time is shown next to each price.</p>';
UPDATE app.faq_items SET answer_fa = '<p>کاربران رایگان قیمت جهانی فلزات، قیمت‌های بورس کالا و نمودار یک ماه اخیر این قیمت‌ها را می‌بینند. قیمت روز کالا در بازار آزاد و تالار آهن، تاریخچه‌ی کامل نمودارها و امکانات تخصصی دیگر ویژه‌ی اشتراک‌های نقره‌ای و طلایی است.</p>', answer_en = '<p>Free users see global metal prices, IME prices and the last month''s chart of these prices. Day prices of the free market and the Iran Iron Market, full chart history and the specialist features are for Silver and Gold.</p>', updated_at = now() WHERE slug = 'free-plan' AND answer_fa = '<p>کاربران رایگان می‌توانند به اطلاعات عمومی و بخشی از قیمت‌های داخلی و جهانی بازار دسترسی داشته باشند. برخی امکانات تخصصی مانند بخشی از تاریخچه قیمت، تحلیل‌ها، ابزارها و خدمات ویژه برای کاربران دارای اشتراک در نظر گرفته شده است.</p>' AND answer_en = '<p>Free users can access general information and part of the domestic and global market prices. Some specialist features, such as part of the price history, analyses, tools and special services, are reserved for subscribers.</p>';
UPDATE app.faq_items SET answer_fa = '<p>اشتراک نقره‌ای علاوه بر امکانات رایگان، قیمت روز کالا در بازار آزاد و تالار آهن و نمودار و تاریخچه‌ی کامل قیمت کالاها را در اختیار کاربر قرار می‌دهد و برای کاربرانی مناسب است که قیمت و روند بازار را دقیق‌تر دنبال می‌کنند.</p>', answer_en = '<p>On top of the free features, Silver gives the day prices of the free market and the Iran Iron Market and full product charts and history, for users who follow prices and trends closely.</p>', updated_at = now() WHERE slug = 'silver-plan' AND answer_fa = '<p>اشتراک نقره‌ای دسترسی گسترده‌تری به اطلاعات بازار، قیمت محصولات، نمودارها و تاریخچه قیمت در اختیار کاربر قرار می‌دهد و برای کاربرانی مناسب است که به بررسی دقیق‌تر قیمت و روند بازار نیاز دارند.</p>' AND answer_en = '<p>The Silver plan gives wider access to market information, product prices, charts and price history, and suits users who need a closer look at prices and market trends.</p>';
UPDATE app.faq_items SET answer_fa = '<p>اشتراک طلایی کامل‌ترین سطح دسترسی الان‌فلز است و علاوه بر امکانات اشتراک نقره‌ای، مزایدات روزانه، تحلیل و پیش‌بینی بازار، ماشین حساب تخصصی و هشدار پیامکی برای نوسانات شدید قیمت را ارائه می‌دهد.</p>', answer_en = '<p>Gold is the most complete level: on top of Silver it adds daily auctions, market analysis and forecasts, the specialist calculator and SMS alerts for sharp price moves.</p>', updated_at = now() WHERE slug = 'gold-plan' AND answer_fa = '<p>اشتراک طلایی کامل‌ترین سطح دسترسی الان‌فلز است و علاوه بر امکانات اشتراک نقره‌ای، خدماتی مانند تحلیل بازار، پیش‌بینی سناریوهای احتمالی قیمت، اطلاعات حراج‌های روزانه، ماشین حساب قیمت و سرویس‌های اعلان و پیامک را ارائه می‌دهد.</p>' AND answer_en = '<p>Gold is the most complete level of access. On top of everything in Silver, it offers market analysis, possible price scenarios, daily auction information, the price calculator, and notification and SMS services.</p>';
UPDATE app.faq_items SET answer_fa = '<p>خیر. اشتراک خودکار تمدید نمی‌شود و هیچ مبلغی بدون پرداخت مستقیم شما کسر نمی‌شود. از یک هفته قبل از پایان اشتراک، پیامک یادآوری برایتان ارسال می‌شود (۷ روز، ۳ روز و ۱ روز قبل از پایان و روز پایان). اگر پیش از پایان، همان اشتراک را دوباره بخرید، دوره‌ی جدید از پایان دوره‌ی فعلی شروع می‌شود و روزی از دست نمی‌رود.</p>', answer_en = '<p>No. Subscriptions don''t renew automatically and nothing is charged without your own payment. From a week before your plan ends you get SMS reminders (7, 3 and 1 day before, and on the day it ends). Buying the same plan again before it ends starts the new period when the current one ends, so no day is lost.</p>', updated_at = now() WHERE slug = 'auto-renewal' AND answer_fa = '<p>تمدید اشتراک مطابق شرایط اعلام‌شده هنگام خرید انجام می‌شود. وضعیت تمدید و تاریخ پایان اشتراک از طریق حساب کاربری قابل مشاهده خواهد بود.</p>' AND answer_en = '<p>Renewal follows the terms shown when you buy. The renewal status and end date of your subscription are visible in your account.</p>';
UPDATE app.faq_items SET answer_fa = '<p>خیر. هشدارهای پیامکی قیمت جزو اشتراک طلایی است و هزینه‌ی جداگانه ندارد. پیامک‌های مربوط به حساب و اشتراک، مانند کد ورود و یادآوری پایان اشتراک، برای همه‌ی کاربران رایگان است.</p>', answer_en = '<p>No. SMS price alerts are included in Gold at no extra cost. Account and subscription messages, such as sign-in codes and renewal reminders, are free for everyone.</p>', updated_at = now() WHERE slug = 'sms-cost' AND answer_fa = '<p>هزینه و شرایط استفاده از سرویس پیامک مطابق بسته خدماتی و نوع اشتراک کاربر در صفحه اشتراک‌ها اعلام می‌شود.</p>' AND answer_en = '<p>The cost and terms of the SMS service are shown on the subscriptions page, according to the service package and your plan.</p>';
UPDATE app.faq_items SET answer_fa = '<p>در صفحه‌ی ورود روی «رمز عبور را فراموش کرده‌اید؟» بزنید و شماره‌ی موبایل حساب خود را وارد کنید. یک کد تأیید برایتان پیامک می‌شود؛ پس از وارد کردن کد، نام کاربری شما نمایش داده می‌شود و می‌توانید رمز عبور جدید تعیین کنید.</p>', answer_en = '<p>On the sign-in page choose “Forgot your password?” and enter your account''s mobile number. You''ll get a code by SMS; after entering it you see your username and choose a new password.</p>', updated_at = now() WHERE slug = 'forgot-password' AND answer_fa = '<p>در صفحه ورود، گزینه «فراموشی رمز عبور» را انتخاب کنید و اطلاعات مورد نیاز را وارد کنید. مراحل بازیابی حساب از طریق روش ارتباطی ثبت‌شده برای شما ارسال خواهد شد.</p>' AND answer_en = '<p>On the login page choose “Forgot password” and enter the requested details. The account recovery steps will be sent to the contact method registered for you.</p>';
UPDATE app.faq_items SET answer_fa = '<p>از صفحه‌ی «تماس با ما» پیام بفرستید، یا اگر وارد حساب کاربری شده‌اید، در بخش پشتیبانی حساب تیکت ثبت کنید. تلفن و سایر راه‌های ارتباطی نیز پس از اعلام، در صفحه‌ی «تماس با ما» و پایین صفحه‌های سایت نمایش داده می‌شوند.</p>', answer_en = '<p>Send a message from the “Contact us” page or, when signed in, open a ticket in your account''s support section. The phone number and other contact details are shown on the contact page and in the footer once announced.</p>', updated_at = now() WHERE slug = 'contact-support' AND answer_fa = '<p>کاربران می‌توانند از طریق بخش «تماس با ما» و روش‌های ارتباطی اعلام‌شده در سایت، مانند تلفن، ایمیل، پیام‌رسان یا تیکت پشتیبانی با تیم الان‌فلز در ارتباط باشند.</p>' AND answer_en = '<p>You can reach the Alan Felez team through the “Contact us” section and the contact methods listed on the site, such as phone, e-mail, messengers or a support ticket.</p>';
UPDATE app.faq_items SET answer_fa = '<p>قیمت‌های بورس کالا برای همه‌ی کاربران رایگان است و در صفحه‌ی قیمت فلزات، همراه با منبع و زمان آخرین به‌روزرسانی، نمایش داده می‌شود.</p>', answer_en = '<p>IME prices are free for everyone and are shown on the metal prices page with their source and last-updated time.</p>', updated_at = now() WHERE slug = 'ime-data' AND answer_fa = '<p>اطلاعات مرتبط با معاملات و قیمت‌های بورس کالا، متناسب با نوع محصول و داده‌های در دسترس، در بخش مربوطه ارائه می‌شود تا کاربران بتوانند وضعیت بازار داخلی را بهتر بررسی کنند.</p>' AND answer_en = '<p>Information on Iran Mercantile Exchange trades and prices is presented in the relevant section, depending on the product and the data available, so users can better assess the domestic market.</p>';
UPDATE app.faq_items SET answer_fa = '<p>بله. قیمت‌های بورس کالا و نمودار یک ماه اخیر آن‌ها برای همه قابل مشاهده است و تاریخچه‌ی کامل‌تر برای مشترکان نقره‌ای و طلایی در دسترس است.</p>', answer_en = '<p>Yes. IME prices and their last month''s chart are open to everyone; the longer history is for Silver and Gold subscribers.</p>', updated_at = now() WHERE slug = 'ime-trades-and-prices' AND answer_fa = '<p>بسته به نوع داده و سطح دسترسی کاربر، اطلاعات مرتبط با معاملات، عرضه‌ها و قیمت‌های بورس کالا در بخش مربوطه قابل مشاهده و بررسی خواهد بود.</p>' AND answer_en = '<p>Depending on the type of data and your access level, information on IME trades, offerings and prices can be viewed and reviewed in the relevant section.</p>';
UPDATE app.faq_items SET question_fa = 'مزایدات الان‌فلز چیست؟', answer_fa = '<p>در بخش «مزایدات»، اطلاعات مزایده‌های فلزات، شامل شمش و محصولات میانی، ضایعات و مواد اولیه، منتشر می‌شود. الان‌فلز برگزارکننده‌ی این مزایده‌ها نیست و اطلاعات آن‌ها صرفاً جهت اطلاع منتشر می‌شود؛ شرایط و مهلت قطعی هر مزایده را در آگهی برگزارکننده بررسی کنید.</p>', question_en = 'What are Alan Felez auctions?', answer_en = '<p>The “Auctions” section publishes metal auctions: ingots and intermediate products, scrap and raw materials. Alan Felez doesn''t run them; the details are for information, so check each auction''s terms and deadline in the organiser''s notice.</p>', updated_at = now() WHERE slug = 'daily-auctions' AND question_fa = 'حراج‌های روزانه چیست؟' AND answer_fa = '<p>حراج‌های روزانه شامل اطلاعات مربوط به عرضه‌ها و معاملات روزانه محصولات مختلف است که می‌تواند برای بررسی وضعیت عرضه، قیمت و شرایط بازار مورد استفاده قرار گیرد.</p>' AND question_en = 'What are the daily auctions?' AND answer_en = '<p>Daily auctions cover information on the daily offerings and trades of different products, which can be used to assess supply, prices and market conditions.</p>';
UPDATE app.faq_items SET question_fa = 'چه اطلاعاتی از مزایده‌ها نمایش داده می‌شود؟', answer_fa = '<p>موضوع، فلز، دسته، حجم و وضعیت هر مزایده برای همه‌ی کاربران نمایش داده می‌شود. مهلت شرکت، محل، برگزارکننده، توضیحات و فایل آگهی مزایده ویژه‌ی مشترکان طلایی است.</p>', question_en = 'What auction details are shown?', answer_en = '<p>Every auction''s title, metal, category, quantity and status are shown to everyone. The deadline, place, organiser, details and the notice file are for Gold subscribers.</p>', updated_at = now() WHERE slug = 'who-uses-auction-data' AND question_fa = 'تحلیل حراج‌های روزانه برای چه کسانی کاربرد دارد؟' AND answer_fa = '<p>این اطلاعات می‌تواند برای تولیدکنندگان، بازرگانان، تأمین‌کنندگان و سایر فعالان بازار که روند عرضه و قیمت محصولات را دنبال می‌کنند مفید باشد.</p>' AND question_en = 'Who is daily auction analysis useful for?' AND answer_en = '<p>This information can be useful for producers, traders, suppliers and other market players who follow supply and price trends.</p>';
UPDATE app.faq_items SET answer_fa = '<p>بله. تحلیل بازار و سناریوهای احتمالی حرکت قیمت، بر اساس داده‌ها و شرایط موجود، برای مشترکان طلایی ارائه می‌شود. این پیش‌بینی‌ها قطعی نیستند و توصیه‌ی خرید یا فروش محسوب نمی‌شوند.</p>', answer_en = '<p>Yes. Market analysis and possible price scenarios, based on the data and conditions at the time, are offered to Gold subscribers. They are not certain and are not advice to buy or sell.</p>', updated_at = now() WHERE slug = 'price-forecasts' AND answer_fa = '<p>در سطح خدمات مربوط به این قابلیت، الان‌فلز بر اساس داده‌ها و شرایط موجود، سناریوهای احتمالی حرکت قیمت و تحلیل بازار را ارائه می‌کند.</p>' AND answer_en = '<p>For the services that include this feature, Alan Felez presents possible price scenarios and market analysis based on the data and conditions available.</p>';
UPDATE app.faq_categories SET name_fa = 'بورس کالا و مزایدات', updated_at = now() WHERE slug = 'ime' AND name_fa = 'بورس کالا و حراج‌های روزانه';
UPDATE app.faq_categories SET name_en = 'Commodity exchange & auctions', updated_at = now() WHERE slug = 'ime' AND name_en = 'Commodity exchange & daily auctions';

